-- 6.1.1.4 Last-contact data pull - most recent inbound/outbound event per client, grounded in §16.5 communication_events
SELECT client_id, MAX(occurred_at) AS last_contact_at, COUNT(*) FILTER (WHERE occurred_at > now() - interval '30 days') AS touches_last_30d
FROM communication_events
WHERE client_id = {{ $json.client_id }}
GROUP BY client_id;

