// 6.1.1.5 - Merge + health-score compute
// FLAG: the weighting below is a transparent, documented placeholder - it is NOT a confirmed
// business rule from any source file (no health-score rubric exists in the uploads). Per the
// golden rule (never invent thresholds and present them as final), this must be reviewed and
// approved by Nivy before being used for any customer-facing or renewal-affecting decision.
// The raw component values ARE real (grounded in communication_events / Metabase / clients_master).

const account = $('Get Active Accounts').item.json;
const contact = $('Last-Contact Data Pull').all().find(i => i.json.client_id === account.client_id) || {};
const usage = $('Usage-Data Pull (Metabase)').item.json || {};
const tickets = $('MOCK_TICKETING_PROVIDER - Tickets Pull').item?.json || null;

const lastContactAt = contact.last_contact_at || account.last_reply_at || account.last_nurture_sent || null;
const daysSinceContact = lastContactAt ? Math.floor((Date.now() - new Date(lastContactAt).getTime()) / 86400000) : null;

// PLACEHOLDER SCORING - flagged, not final:
let score = 100;
if (daysSinceContact === null) score -= 20;
else if (daysSinceContact > 60) score -= 40;
else if (daysSinceContact > 30) score -= 20;
else if (daysSinceContact > 14) score -= 10;

if (account.status === 'Churn Risk') score -= 30;
if (account.status === 'Payment Failed') score -= 30;
if (account.dunning_attempts > 0) score -= (account.dunning_attempts * 10);

if (tickets && typeof tickets.open_count === 'number' && tickets.open_count > 3) score -= 10;

score = Math.max(0, Math.min(100, score));

return [{
  json: {
    client_id: account.client_id,
    odoo_lead_id: account.odoo_lead_id,
    snapshot_date: new Date().toISOString().slice(0,10),
    days_since_last_contact: daysSinceContact,
    touches_last_30d: contact.touches_last_30d ?? null,
    usage_raw: usage && !usage.error ? usage : null,
    ticket_data_source: 'MOCK - ticketing tool undecided, see §0.3',
    health_score_raw: score,
    health_score_methodology_status: 'PLACEHOLDER - needs business confirmation, not yet approved'
  }
}];

