-- 6.1.1.6a - schema setup (idempotent, safe to run every time - matches ALTER TABLE IF NOT EXISTS pattern used everywhere else)
ALTER TABLE clients_master ADD COLUMN IF NOT EXISTS health_score INTEGER;
ALTER TABLE clients_master ADD COLUMN IF NOT EXISTS health_score_snapshot_at TIMESTAMP;

UPDATE clients_master
SET health_score = {{ $json.health_score_raw }},
    health_score_snapshot_at = now(),
    updated_at = now()
WHERE id = {{ $json.client_id }};

